import{_ as t,a0 as l,w as r,s as o,ao as d,I as p,x as n,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"从 Linux 命令行进行打印 | LCTT x X-CMD","titleTemplate":false,"description":"从 Linux 命令行进行打印 | LCTT (202101) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"从 Linux 命令行进行打印 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"从 Linux 命令行进行打印 | LCTT (202101) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202101/20190322 Printing from the Linux command line","title":"从 Linux 命令行进行打印","tag":"202101","desc":""},"relativePath":"202101/20190322 Printing from the Linux command line.md","filePath":"[post].md"}'),c={name:"202101/20190322 Printing from the Linux command line.md"};function h(g,s,k,u,b,m){const a=l("Link");return r(),o("div",null,[s[15]||(s[15]=d(`<h1 id="从-linux-命令行进行打印" tabindex="-1">从 Linux 命令行进行打印 <a class="header-anchor" href="#从-linux-命令行进行打印" aria-label="Permalink to “从 Linux 命令行进行打印”">​</a></h1><blockquote><p>在 Linux 命令行进行打印的内容比单单一个 <code>lp</code> 命令多得多，让我们来看一些可用选项。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/03/printouts-paper-100791390-large.jpg" alt="Sherry CC BY 2.0"></p><p>Linux 命令行打印很容易。你可以使用 <code>lp</code> 命令来请求打印，并使用 <code>lpq</code> 命令来查看队列中有哪些打印作业，但是当你要双面打印或使用纵向模式时，这些会变得有些复杂。你可能还需要做很多其他事情，例如打印多份文档副本或取消打印作业。让我们来看看一些选项，当你从命令行打印时，如何让你的打印输出看起来如你所愿。</p><h3 id="显示打印机配置" tabindex="-1">显示打印机配置 <a class="header-anchor" href="#显示打印机配置" aria-label="Permalink to “显示打印机配置”">​</a></h3><p>要从命令行查看打印机设置，请使用 <code>lpoptions</code> 命令。 输出应如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpoptions</span></span>
<span class="line"><span>copies=1 device-uri=dnssd://HP%20Color%20LaserJet%20CP2025dn%20(F47468)._pdl-datastream._tcp.local/ finishings=3 job-cancel-after=10800 job-hold-until=no-hold job-priority=50 job-sheets=none,none marker-change-time=1553023232 marker-colors=#000000,#00FFFF,#FF00FF,#FFFF00 marker-levels=18,62,62,63 marker-names=&#39;Black\\ Cartridge\\ HP\\ CC530A,Cyan\\ Cartridge\\ HP\\ CC531A,Magenta\\ Cartridge\\ HP\\ CC533A,Yellow\\ Cartridge\\ HP\\ CC532A&#39; marker-types=toner,toner,toner,toner number-up=1 printer-commands=none printer-info=&#39;HP Color LaserJet CP2025dn (F47468)&#39; printer-is-accepting-jobs=true printer-is-shared=true printer-is-temporary=false printer-location printer-make-and-model=&#39;HP Color LaserJet cp2025dn pcl3, hpcups 3.18.7&#39; printer-state=3 printer-state-change-time=1553023232 printer-state-reasons=none printer-type=167964 printer-uri-supported=ipp://localhost/printers/Color-LaserJet-CP2025dn sides=one-sided</span></span></code></pre></div><p>如果将其空格转换为回车符，输出可能会更人性化，请注意列出了多少设置选项。</p><p>注意：在下面的输出中，一些行被重新链接，以使输出更具可读性。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpoptions | tr &quot; &quot; &#39;\\n&#39;</span></span>
<span class="line"><span>copies=1</span></span>
<span class="line"><span>device-uri=dnssd://HP%20Color%20LaserJet%20CP2025dn%20(F47468)._pdl-datastream._tcp.local/</span></span>
<span class="line"><span>finishings=3</span></span>
<span class="line"><span>job-cancel-after=10800</span></span>
<span class="line"><span>job-hold-until=no-hold</span></span>
<span class="line"><span>job-priority=50</span></span>
<span class="line"><span>job-sheets=none,none</span></span>
<span class="line"><span>marker-change-time=1553023232</span></span>
<span class="line"><span>marker-colors=#000000,#00FFFF,#FF00FF,#FFFF00</span></span>
<span class="line"><span>marker-levels=18,62,62,63</span></span>
<span class="line"><span>marker-names=&#39;Black\\ Cartridge\\ HP\\ CC530A,</span></span>
<span class="line"><span>Cyan\\ Cartridge\\ HP\\ CC531A,</span></span>
<span class="line"><span>Magenta\\ Cartridge\\ HP\\ CC533A,</span></span>
<span class="line"><span>Yellow\\ Cartridge\\ HP\\ CC532A&#39;</span></span>
<span class="line"><span>marker-types=toner,toner,toner,toner</span></span>
<span class="line"><span>number-up=1</span></span>
<span class="line"><span>printer-commands=none</span></span>
<span class="line"><span>printer-info=&#39;HP Color LaserJet CP2025dn (F47468)&#39;</span></span>
<span class="line"><span>printer-is-accepting-jobs=true</span></span>
<span class="line"><span>printer-is-shared=true</span></span>
<span class="line"><span>printer-is-temporary=false</span></span>
<span class="line"><span>printer-location</span></span>
<span class="line"><span>printer-make-and-model=&#39;HP Color LaserJet cp2025dn pcl3, hpcups 3.18.7&#39;</span></span>
<span class="line"><span>printer-state=3</span></span>
<span class="line"><span>printer-state-change-time=1553023232</span></span>
<span class="line"><span>printer-state-reasons=none</span></span>
<span class="line"><span>printer-type=167964</span></span>
<span class="line"><span>printer-uri-supported=ipp://localhost/printers/Color-LaserJet-CP2025dn</span></span>
<span class="line"><span>sides=one-sided</span></span></code></pre></div><p>使用 <code>-v</code> 选项时，<code>lpinfo</code> 命令将列出驱动程序和相关信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpinfo -v</span></span>
<span class="line"><span>network ipp</span></span>
<span class="line"><span>network https</span></span>
<span class="line"><span>network socket</span></span>
<span class="line"><span>network beh</span></span>
<span class="line"><span>direct hp</span></span>
<span class="line"><span>network lpd</span></span>
<span class="line"><span>file cups-brf:/</span></span>
<span class="line"><span>network ipps</span></span>
<span class="line"><span>network http</span></span>
<span class="line"><span>direct hpfax</span></span>
<span class="line"><span>network dnssd://HP%20Color%20LaserJet%20CP2025dn%20(F47468)._pdl-datastream._tcp.local/ &lt;== printer</span></span>
<span class="line"><span>network socket://192.168.0.23 &lt;== printer IP</span></span></code></pre></div><p><code>lpoptions</code> 命令将显示默认打印机的设置。使用 <code>-p</code> 选项指定其中一个可用打印机代号：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpoptions -p LaserJet</span></span></code></pre></div><p><code>lpstat -p</code> 命令显示打印机的状态，而 <code>lpstat -p -d</code> 列出可用打印机列表。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpstat -p -d</span></span>
<span class="line"><span>printer Color-LaserJet-CP2025dn is idle. enabled since Tue 19 Mar 2019 05:07:45 PM EDT</span></span>
<span class="line"><span>system default destination: Color-LaserJet-CP2025dn</span></span></code></pre></div><h3 id="非常有用的命令" tabindex="-1">非常有用的命令 <a class="header-anchor" href="#非常有用的命令" aria-label="Permalink to “非常有用的命令”">​</a></h3><p>要在默认打印机上打印文档，只需使用 <code>lp</code> 命令，后跟要打印的文件名即可。 如果文件名包含空格（在 Linux 系统上很少见），请将该名称放在引号中或开始输入文件名并按 <code>Tab</code> 键调用空格的转义标志（如下面的第二个示例所示）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lp &quot;never leave home angry&quot;</span></span>
<span class="line"><span>$ lp never\\ leave\\ home\\ angry</span></span></code></pre></div><p><code>lpq</code> 命令显示打印队列：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpq</span></span>
<span class="line"><span>Color-LaserJet-CP2025dn is ready and printing</span></span>
<span class="line"><span>Rank Owner Job File(s) Total Size</span></span>
<span class="line"><span>active shs 234 agenda 2048 bytes</span></span></code></pre></div><p>使用 <code>-n</code> 选项时，<code>lp</code> 命令可用来指定所需打印输出的份数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lp -n 11 agenda</span></span></code></pre></div><p>要取消打印作业，可以使用 <code>cancel</code> 或 <code>lprm</code> 命令。如果没来得及执行，则可能会看到以下信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cancel 229</span></span>
<span class="line"><span>cancel: cancel-job failed: Job #229 is already completed - can&#39;t cancel.</span></span></code></pre></div><h3 id="双面打印" tabindex="-1">双面打印 <a class="header-anchor" href="#双面打印" aria-label="Permalink to “双面打印”">​</a></h3><p>要以双面模式打印，你可以在 <code>lp</code> 命令中使用 <code>sides</code> 选项，该选项不但表示了在纸张的正反面进行打印，还表示了从纸张的哪个边开始打印。这个设置代表了你期望以双面纵向文档的正常方式打印。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lp -o sides=two-sided-long-edge Notes.pdf</span></span></code></pre></div><p>如果要所有文档以双面模式打印，则可以使用 <code>lpoptions</code> 命令更改 <code>sides</code> 设置以修改 <code>lp</code> 的设置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpoptions -o sides=two-sided-short-edge</span></span></code></pre></div><p>要恢复为单面打印，可以使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lpoptions -o sides=one-sided</span></span></code></pre></div><h4 id="横向打印" tabindex="-1">横向打印 <a class="header-anchor" href="#横向打印" aria-label="Permalink to “横向打印”">​</a></h4><p>要以横向模式打印，可以在 <code>lp</code> 命令中使用 <code>landscape</code> 选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lp -o landscape penguin.jpg</span></span></code></pre></div><h3 id="cups-unix-通用打印系统" tabindex="-1">CUPS（Unix 通用打印系统） <a class="header-anchor" href="#cups-unix-通用打印系统" aria-label="Permalink to “CUPS（Unix 通用打印系统）”">​</a></h3><p>Linux 系统上使用的打印系统是基于标准的开源打印系统，称为 <strong>CUPS</strong>，原意是<ruby>Unix 通用打印系统<rt>Common Unix Printing System</rt></ruby>。 它允许计算机充当打印服务器。</p><hr>`,38)),p("p",null,[s[1]||(s[1]=n("via: ",-1)),e(a,{href:"https://www.networkworld.com/article/3373502/printing-from-the-linux-command-line.html"},{default:i(()=>[...s[0]||(s[0]=[n("https://www.networkworld.com/article/3373502/printing-from-the-linux-command-line.html",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=n("作者：",-1)),e(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[n("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=n(" 选题：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[n("lujun9972",-1)])]),_:1}),s[8]||(s[8]=n(" 译者：",-1)),e(a,{href:"https://github.com/stevenzdg988"},{default:i(()=>[...s[4]||(s[4]=[n("stevenzdg988",-1)])]),_:1}),s[9]||(s[9]=n(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[n("Linux中国",-1)])]),_:1}),s[14]||(s[14]=n(" 荣誉推出",-1))])])}const x=t(c,[["render",h]]);export{y as __pageData,x as default};
